  "source": "type EdgeReq = {
  body: Record<string, unknown>;
  query: Record<string, unknown>;
  params: Record<string, string>;
  method: string;
  headers: Record<string, string | undefined>;
};

type EdgeRes = {
  json: (data: unknown) => unknown;
  send: (data: unknown) => unknown;
  status: (code: number) => EdgeRes;
};

const edgeReq = req as EdgeReq;
const edgeRes = res as EdgeRes;

function toFiniteNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) {
      return parsed;
    }
  }

  return null;
}

async function handler(): Promise<void> {
  const a = toFiniteNumber(edgeReq.body.a);
  const b = toFiniteNumber(edgeReq.body.b);

  if (a === null || b === null) {
    edgeRes.status(400).json({
      success: false,
      error: "Both \"a\" and \"b\" are required finite numbers.",
    });
    return;
  }

  const sum = a + b;

  edgeRes.json({
    success: true,
    data: {
      a,
      b,
      result: sum,
      sum,
    },
  });
}",
